# owner: platform
"""Weekly timesheet lines built from shifts."""

from collections import defaultdict
from typing import Iterable, List

from hourglass.models import Shift


def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts to total")
    if any(not item.worker.strip() for item in shifts):
        raise ValueError("shift has a blank worker name")


def _totals(shifts: List[Shift]) -> dict:
    sums = defaultdict(lambda: [0, 0])
    for item in shifts:
        entry = sums[item.worker]
        entry[0] += 1
        entry[1] += item.span.minutes
    return sums


def _rank(pair) -> tuple:
    return (-pair[1][1], pair[0])


def _line(name: str, count: int, minutes: int) -> str:
    return f"{name}: {count} shifts, {minutes / 60:.1f} h"


# ---
def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, busiest first. ValueError if bad."""
    shifts = list(shifts)
    _check(shifts)
    ranked = sorted(_totals(shifts).items(), key=_rank)
    return [_line(name, *vals) for name, vals in ranked]

