# owner: platform
import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines


def _shift(worker, start, end):
    return Shift(worker, "mon", Span(start, end))


class TimesheetTests(unittest.TestCase):
    # ---
    def test_busiest_first(self):
        shifts = [
            _shift("Odell", 540, 600),
            _shift("Brisa", 540, 780),
            _shift("Odell", 660, 720)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 1 shifts, 4.0 h",
                "Odell: 2 shifts, 2.0 h"
            ]
        )

    # ---
    def test_one_decimal(self):
        lines = timesheet_lines([_shift("Quill", 0, 100)])
        self.assertEqual(lines, ["Quill: 1 shifts, 1.7 h"])

    # ---
    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    # ---
    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_lines([_shift("  ", 0, 60)])
